import { Injectable } from '@angular/core';

@Injectable()
export class AppConfig {

    constructor() { }

    static configFileUrl = 'assets/config/config.json';
    //   static configFile: CommonConfig;
    static tenantId: string;
    static baseApi = ''; // 后台数据基础地址，例如/cpacs
    static devConfig = {
        i18n: {
            'defaultLang': 'zh-CN',
            'langsList': ['zh-CN', 'en-US', 'zh-MO'],
            'langsDetail': [
                { 'value': 'zh-CN', 'label': '简体中文' },
                { 'value': 'en-US', 'label': 'English' },
                { 'value': 'zh-MO', 'label': '繁體中文' }
            ]
        },
        url: {
            // 请求公用数据的url，请在setUrl方法中设置
            menuUrl: AppConfig.baseApi + '/menu', // 菜单
            dataDictUrl: AppConfig.baseApi + '/data-dictionary',  // 数据字典
            authServerUrl: AppConfig.baseApi + '/auth/oauth/token', // 登录 和 刷新token
            setDefaultRoleUrl: AppConfig.baseApi + '/common/defaultRole/saveDefaultRole',
            setColsURL: AppConfig.baseApi + '/cols/config',
            setFormConfigURL: AppConfig.baseApi + '/form/config',
            commonConfigUrl: AppConfig.baseApi + '/common/config', // 系统通用的配置数据，缓存进localStorage
            commonBusinessDataUrls: [
                { url: AppConfig.baseApi + '/business/datalist1', key: 'datalist1' },
                { url: AppConfig.baseApi + '/business/datalist2', key: 'datalist2' },
            ]// app自用的通用业务数据，缓存进localStorage，方便用于下拉选择，例如设备类型、检查类型、检查部位等
        },
        auth: {
            // 请求头信息，固定格式，不需要修改
            authHeaderOptions: { 'Content-type': 'application/json', 'authorization': '' },
            authPrefix: 'Bearer ',
            authServerClientId: 'demo-id', // 选角色改为'demo-chooseRoles-id'
            authServerPassword: 'demo-secret', // 选角色改为'demo-chooseRoles-secret'
            ignoreList: [ // 不携带token的白名单
                AppConfig.baseApi + '/register'
            ]
        },
        date: {
            dateFormat: 'yy/mm/dd',
            dateFormatTemp: 'yyyy/MM/dd',
            dateTimeFormatTemp1: 'yyyy/MM/dd hh:mm',
            dateTimeFormatTemp2: 'yyyy/MM/dd hh:mm:ss'
        },
        time: {
            debounceTime: 300 // 毫秒防抖
        },
        errorMessages: {
            // 请求失败的错误提示，项目组自行修改和补充
            // 注意：内容已做国际化，请到assets/i18n/zh.json中修改相关内容
            httpErrorTitle: '',
            httpErrorMessages: {},
            // angular常用表单验证的提示信息
            // 注意：内容已做国际化，请到assets/i18n/zh.json中修改相关内容
            validatorError: {},
        },
        other: {
            ifUseTenantId: false, // 是否使用租户id
            ifChooseRoleOnLogin: false, // 是否在登录时选角色
            // 登录和权限配置
            ifUseToken: true, // 是否使用token: 默认为true
            ifLogin: true, // 是否使用登录页
            indexUrl: '/dashboard/admin', // 首页地址,用于不用登陆时面包屑跳转
            ifUseTopBar: true, // todo 是否使用topbar
            ifUseMenu: true, // todo 是否使用menu
            // 日期控件的中文显示
            calendarZH: {
                firstDayOfWeek: 0,
                dayNames: ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'],
                dayNamesShort: ['周日', '周一', '周二', '周三', '周四', '周五', '周六'],
                dayNamesMin: ['日', '一', '二', '三', '四', '五', '六'],
                monthNames: ['一月', '二月', '三月', '四月', '五月', '六月', '七月', '八月', '九月', '十月', '十一月', '十二月'],
                monthNamesShort: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
                today: '今天',
                clear: '清空'
            },
            // 多选控件的中文显示
            multiSelectZH: '已选 {0} 项'
        }
    };
}
