import {ChangeDetectorRef, Component, ElementRef, Injector, OnInit, ViewChild} from '@angular/core';
import { ActivatedRoute, NavigationExtras, Router } from '@angular/router';
import { isNotNullOrUndefined } from 'codelyzer/util/isNotNullOrUndefined';
import { Plugins } from '@capacitor/core';
// 扫描码
import 'scanner';
import { Platform } from '@ionic/angular';
import { AppConfig } from '../app.config';
import { HttpClientService } from '../shared/http-client.service';
import { ModalService } from 'ng-zorro-antd-mobile';
import {environment} from "../../environments/environment";
const { Scanner } = Plugins;
//
// import {Keyboard} from '@ionic-native/keyboard';

@Component({
    selector: 'app-tab1',
    templateUrl: 'tab1.page.html',
    styleUrls: ['tab1.page.scss']
})
export class Tab1Page implements OnInit {
    removeScannerHandler;
    UserName = '';
    modelShow = false;
    barcode;
    censusAddress;
    loginTitle = '核酸检测平台-采集';
    isMove = false;
    sampleInfo = {
        dayUserCollectPatientNum: '---',
        dayUserCollectTubeNum: '---',
        totalUserCollectPatientNum: '---',
        totalUserCollectTubeNum: '---',
    };
    selectRegisterType = '0'; // 0 自愿者 1 护士
    constructor(
        private router: Router,
        private http: HttpClientService,
        private platform: Platform,
        private eleRef: ElementRef,
        private alertModal: ModalService,
        private route: ActivatedRoute,
        private changeRef: ChangeDetectorRef,
    ) {
        this.platform.backButton.subscribe(() => {
            if (this.router.url.indexOf('tab1') > -1) {
                this.router.navigate(['/login']);
            }
        });
    }
    tab1ModelDisplay;
    state = {
        data: ['AiyWuByWklrrUDlFignR', 'TekJlZRVCjLFexlOCuWn', 'IJOtIlfsYdTyaDTRVrLI'],
        imgHeight: '184px'
    };
    load;
    @ViewChild('boxInfo', { static: false }) boxInfo;
    closeBoxInfo;
    ngOnInit(): void {
        this.tab1ModelDisplay = document.getElementsByClassName('tab1-load-model')[0];
        this.load = document.getElementsByClassName('tab1-load-bar')[0];
        this.route.queryParams.subscribe(data => {
            if (data['boxBarcode'] !== undefined) {
                this.http.showToast('封管失败，' + data['boxBarcode'] + '箱子已满，请扫码新的箱码，该试管会自动封管并关联到新的箱子中。');
                this.isMove = true;
            } else {
                this.isMove = false;
            }
        });
    }
    ionViewWillEnter() {
        this.UserName = sessionStorage.getItem('loginUserName');
        this.censusAddress = sessionStorage.getItem('censusAddress');
        this.changeRef.markForCheck();
        this.changeRef.detectChanges();
        console.log('1111');
        this.tab1ModelDisplay = document.getElementsByClassName('tab1-load-model')[0];
        this.getRcpName();
        // this.getSampleByUser();
    }
    // 路由返回
    showAlert() {
        this.alertModal.alert('', '确认退出?', [
            { text: '取消', onPress: () => { } },
            {
                text: '退出', onPress: () => {
                    sessionStorage.clear();
                    this.router.navigate(['/login']);
                }
            }
        ]);
    }
    routeBack() {
        this.showCustom(false);
        this.showAlert();
    }
    navTo(dest){
        this.router.navigate([dest]);
    }

    boxListClick() {
        this.showCustom(false);
        this.router.navigate(['/BoxList']);
    }
    async clickScan() {
        try {
            const result = await Scanner.openScanner();
            switch (result['operation']) {
                case 'SCAN':
                    this.ScanBoxOperate(result['result']);
                    break;
                case 'MANUAL':
                    this.showCustom(true);
                    break;
                case 'CANCEL':
                    break;
            }
        } catch (e) {
            this.showCustom(true);
        }
    }

    showBoxInfoAlert(data) {
            this.closeBoxInfo = data;
            this.alertModal.alert('转运箱:' + data['boxBarcode'],
            this.boxInfo, [
            { text: '开箱', onPress: () => {
                 this.OpenBoxOperate( data['boxBarcode']);
                } },
            {
                text: '取消', onPress: () => {
                }
            }
        ]);
    }
    //  弹框
    showCustom(value) {
        this.barcode = undefined;
        if (value) {
            this.eleRef.nativeElement.querySelector('.tab1-load-model')['style']['display'] = 'inline-block';
            this.changeRef.markForCheck();
            this.changeRef.detectChanges();
            this.eleRef.nativeElement.querySelector('.tab1-load-model-input').focus();
            const keyboard = Plugins.Keyboard;
            keyboard.show();
        } else {
            this.eleRef.nativeElement.querySelector('.tab1-load-model')['style']['display'] = 'none';
        }
    }

    // 保存箱码
    ScanBoxOperate(barcode) {
        if (isNotNullOrUndefined(barcode) && barcode.trim() !== '') {
            if (!this.http.CheckNumberAndEnglish(barcode)){
                this.http.showToast('箱码中存在除数字和大写字母外的字符，请重新扫描或输入！');
                return;
            }
            if (barcode.length !== 6){
                if (!this.http.generateBarcode(barcode) || barcode.length < 8){
                        this.http.showToast('箱码校验失败，请重新扫描或输入！');
                        return;
                    }
            }
        } else {
            this.http.showToast('箱码为空，请重新扫描或输入！');
            return;
        }
        this.showCustom(false);
        this.OpenBoxOperate(barcode);
        // 查询后台箱信息
       // this.getBoxInfoById(barcode);
    }
    OpenBoxOperate(barcode) {
        const condition = {
            boxBarcode: barcode,
            boxState: 'OpenBox'
        };
        this.load['style']['display'] = 'inline-block';
        this.http
            .get(`rcp/api/box/operate/scan`, condition, '扫描转运箱条码', environment.FailMessage.openBox)
            .subscribe(data => {
                this.load['style']['display'] = 'none';
                if (data['isSuccess']) {
                    sessionStorage.setItem('isCloseBox', '0');
                    sessionStorage.setItem('boxBarcode', data['data']['boxBarcode']);
                    sessionStorage.setItem('boxBarId', data['data']['boxBarId']);
                    // 判断是否是移管
                    if (this.isMove) {
                        this.confirmTube();
                    } else {
                        this.router.navigate(['/BottleList']);
                     //   this.router.navigate(['/BottleBarcode']);
                    }
                }
            });
    }

    // 封管操作
    confirmTube() {
        const condition = {
            boxBarId: sessionStorage.getItem('boxBarId'),
            tubeBarId: sessionStorage.getItem('tubeBarId'),
            tubeBarcode: sessionStorage.getItem('tubeBarcode'),
            tubeState: 'CloseBar'
        };
        this.http
            .get(`rcp/api/tube/operate/confirmTube`, condition, '确认采集管', environment.FailMessage.confirmTube)
            .subscribe(data => {
                this.load['style']['display'] = 'none';
                if (data['isSuccess']) {
                    this.router.navigate(['/BottleList']);
                }
            });
    }

    getRcpName() {
        let config = {
            "name": "全场景疫情病原体检测信息系统",
        }
        this.loginTitle = config['name'];
    }

    // 根据用户查当前信息
    getSampleByUser() {
        this.load['style']['display'] = 'inline-block';
        const condition = null;
        this.http
            .get(`rcp/api/box/operate/getCollectNumByUser`, condition, '根据采集员查询采集相关数量', '')
            .subscribe(data => {
                this.load['style']['display'] = 'none';
                if (data['isSuccess']) {
                    this.sampleInfo = data['data'];
                }
            });
    }

    // 根据用户查管
    getTubeByUser() {
        const condition = {
            boxBarId: sessionStorage.getItem('boxBarId')
        };
        this.http
            .get(AppConfig.baseApi + `rcp/api/tube/operate/getTubeByUser`, condition, '根据用户查管', '')
            .subscribe(data => {
                // 判断是否有管
                if (isNotNullOrUndefined(data['data']['tubeId'])) {
                    // 有管, 存管信息
                    sessionStorage.setItem('tubeBarId', data['data']['tubeId']);
                    sessionStorage.setItem('tubeBarcode', data['data']['tubeBarcode']);
                    sessionStorage.setItem('tubeCapacity', data['data']['tubeCapacity']);
                    //  跳转到扫描身份证界面
                    this.router.navigate(['/PersonList']);
                } else {
                    // 无管， 跳转到扫采集管界面
                    this.router.navigate(['/BottleBarcode']);
                }
            });
    }
    // 根据箱编码查询箱信息
    getBoxInfoById(barcode) {
        this.load['style']['display'] = 'inline-block';
        const condition = {
            boxBarcode: barcode
        };
        this.http
            .get(`rcp/api/box/operate/getBoxInfoByBarcode`, condition, '根据箱编码查询箱信息', '查询箱信息失败')
            .subscribe(data => {
                this.load['style']['display'] = 'none';
                if (data['isSuccess']) {
                    switch (data['data']['boxState']){
                        case 'OpenBox':
                            this.OpenBoxOperate(barcode);
                            break;
                        case 'CloseBox':
                            this.showBoxInfoAlert(data['data']);
                            break;
                        case 'Send':
                            this.http.showToast('该转运箱已送检');
                            break;
                        case 'Incept':
                            this.http.showToast('该转运箱已接收');
                            break;
                        default:
                            this.showBoxInfoAlert(data['data']);
                            break;
                    }
                }
            });
    }
    /**
     * 换箱
     */
     clickChange() {
        this.router.navigate(['/changebox']);
    }
    /**
     * 换箱列表
     */
     clickTransferBoxListChange(value) {
         switch (value) {
             case 1:
                 this.router.navigate(['/TransferBoxList']);
                 break;
             case 2:
                 this.router.navigate(['/TubeFindBox']);
                 break;
             case 3:
                 this.router.navigate(['/ModifyPwd']);
                 break;
             case 4:
                 this.router.navigate(['/TubeFindPeople']);
                 break;
             case 5:
                 this.router.navigate(['/CollectionStatistics']);
                 break;
         }
    }
}
